(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10+Math.sin(x*0.04+y*0.03+t*0.7)*5;
  const wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10+Math.cos(x*0.035-y*0.025-t*0.6)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,1.15],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*55,0.085,1.8,0.9]
  ];
  let aS=0,iS=0,pulse=0,cross=0;
  for(let j=0;j<8;j++){
