    aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    pulse+=Math.sin(d*f*0.3-t*sp*1.2)*Math.exp(-d*0.005)*w;
    const n=src[(j+1)%8],d2=Math.sqrt((sx-n[0])**2+(sy-n[1])**2);
    cross+=Math.sin(d*f*0.5+d2*n[2]*0.5-t*sp*0.8)*w*0.5;
  }
  const act=aS/8,inh=iS/8,pul=pulse/8,crs=cross/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.06+sy*0.02-t*1.5)*0.15;
