  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx*0.14+sy*0.14)+t)*0.5+Math.sin((sx*0.1-sy*0.18)-t*0.7)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+crs*0.4+pul*0.3)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+moire*0.15)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.2+Math.tanh(pul)*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,58],[12,48,98],[20,95,125],[30,155,138],[75,182,105],[175,198,62],[228,178,48],[218,128,58],[198,78,62],[158,42,68],[95,22,62],[50,14,56],[5,12,58]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.5?1.05:0.95;
  const glow=Math.max(0,Math.abs(reaction)-0.6)*2.5;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0),
